CREATE TABLE users (id UUID PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, is_admin BOOLEAN NOT NULL DEFAULT false, status TEXT NOT NULL CHECK (status IN ('ACTIVE','DISABLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE devices (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, user_agent TEXT NOT NULL, first_seen_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX devices_user_last_seen_idx ON devices (user_id, last_seen_at DESC);
CREATE TABLE sessions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE, token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32), expires_at TIMESTAMPTZ NOT NULL, absolute_expires_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, last_ip INET, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (expires_at <= absolute_expires_at));
CREATE INDEX sessions_user_revoked_expires_idx ON sessions (user_id, revoked_at, expires_at);
CREATE TABLE messages (id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, body_plaintext TEXT, body_ciphertext BYTEA, body_nonce BYTEA, body_encryption_version SMALLINT, body_format TEXT NOT NULL, detected_type TEXT, detected_language TEXT, sensitive BOOLEAN NOT NULL DEFAULT false, lifecycle TEXT NOT NULL CHECK (lifecycle IN ('TEMPORARY','PERMANENT')), is_favorite BOOLEAN NOT NULL DEFAULT false, expires_at TIMESTAMPTZ, trashed_at TIMESTAMPTZ, purge_at TIMESTAMPTZ, source_user_id UUID REFERENCES users(id) ON DELETE SET NULL, source_message_id UUID REFERENCES messages(id) ON DELETE SET NULL, created_device_id UUID REFERENCES devices(id) ON DELETE SET NULL, version BIGINT NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK ((NOT sensitive AND body_ciphertext IS NULL AND body_nonce IS NULL AND body_encryption_version IS NULL) OR (sensitive AND body_plaintext IS NULL AND body_ciphertext IS NOT NULL AND body_nonce IS NOT NULL AND body_encryption_version IS NOT NULL AND octet_length(body_nonce) = 12)), CHECK ((lifecycle = 'TEMPORARY' AND expires_at IS NOT NULL) OR (lifecycle = 'PERMANENT' AND expires_at IS NULL)), CHECK (NOT is_favorite OR lifecycle = 'PERMANENT'), CHECK ((trashed_at IS NULL) = (purge_at IS NULL)));
CREATE INDEX messages_owner_lifecycle_idx ON messages (owner_id, lifecycle, trashed_at, created_at DESC, id DESC); CREATE INDEX messages_owner_favorite_idx ON messages (owner_id, is_favorite, trashed_at, created_at DESC, id DESC); CREATE INDEX messages_owner_purge_idx ON messages (owner_id, purge_at); CREATE INDEX messages_owner_expires_idx ON messages (owner_id, expires_at);
CREATE TABLE tags (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, normalized_name TEXT NOT NULL, color TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, normalized_name));
CREATE TABLE message_tags (message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE, tag_id UUID NOT NULL REFERENCES tags(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(message_id, tag_id));
CREATE TABLE file_objects (id UUID PRIMARY KEY, sha256 BYTEA NOT NULL CHECK (octet_length(sha256) = 32), size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), detected_mime TEXT NOT NULL, storage_backend TEXT NOT NULL CHECK (storage_backend = 'filesystem'), storage_key TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('PENDING','READY','DELETING')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), ready_at TIMESTAMPTZ, UNIQUE(sha256, size_bytes)); CREATE INDEX file_objects_status_created_idx ON file_objects(status, created_at);
CREATE TABLE message_attachments (id UUID PRIMARY KEY, message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE, file_object_id UUID NOT NULL REFERENCES file_objects(id), original_filename TEXT NOT NULL, client_mime TEXT, display_order INTEGER NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX message_attachments_message_order_idx ON message_attachments(message_id, display_order); CREATE INDEX message_attachments_file_object_idx ON message_attachments(file_object_id);
CREATE TABLE file_derivatives (id UUID PRIMARY KEY, source_file_id UUID NOT NULL REFERENCES file_objects(id), kind TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), status TEXT NOT NULL CHECK (status IN ('PENDING','READY','FAILED','DELETING')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_file_id, kind));
CREATE TABLE upload_sessions (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, original_filename TEXT NOT NULL, expected_size BIGINT NOT NULL CHECK (expected_size >= 0), client_mime TEXT, chunk_size BIGINT NOT NULL CHECK (chunk_size > 0), status TEXT NOT NULL CHECK (status IN ('CREATED','UPLOADING','COMPLETING','COMPLETED','FAILED','EXPIRED')), file_object_id UUID REFERENCES file_objects(id) ON DELETE SET NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, consumed_message_id UUID REFERENCES messages(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, CHECK (consumed_message_id IS NULL OR consumed_at IS NOT NULL)); CREATE INDEX upload_sessions_user_status_expires_idx ON upload_sessions(user_id, status, expires_at); CREATE INDEX upload_sessions_completed_cleanup_idx ON upload_sessions(completed_at,id) WHERE status='COMPLETED'; CREATE INDEX upload_sessions_handoff_file_idx ON upload_sessions(file_object_id,completed_at) WHERE status='COMPLETED' AND consumed_at IS NULL;
CREATE TABLE upload_parts (upload_session_id UUID NOT NULL REFERENCES upload_sessions(id) ON DELETE CASCADE, part_number INTEGER NOT NULL CHECK (part_number >= 0), size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), completed_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(upload_session_id, part_number));
CREATE TABLE idempotency_keys (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, operation TEXT NOT NULL, key TEXT NOT NULL, request_hash BYTEA NOT NULL CHECK (octet_length(request_hash) = 32), resource_type TEXT, resource_id UUID, response_metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, operation, key)); CREATE INDEX idempotency_keys_expires_idx ON idempotency_keys(expires_at);
CREATE TABLE background_jobs (id UUID PRIMARY KEY, job_type TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id UUID, status TEXT NOT NULL CHECK (status IN ('PENDING','RUNNING','COMPLETED','FAILED')), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), next_run_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, last_error_code TEXT, last_error_summary TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX background_jobs_status_next_run_idx ON background_jobs(status, next_run_at);
CREATE TABLE system_settings (id SMALLINT PRIMARY KEY CHECK (id = 1), temporary_ttl_hours INTEGER NOT NULL DEFAULT 72 CHECK (temporary_ttl_hours > 0), trash_ttl_hours INTEGER NOT NULL DEFAULT 168 CHECK (trash_ttl_hours > 0), max_file_size_bytes BIGINT NOT NULL DEFAULT 2147483648 CHECK (max_file_size_bytes > 0), max_storage_bytes BIGINT CHECK (max_storage_bytes IS NULL OR max_storage_bytes > 0), audit_retention_days INTEGER NOT NULL DEFAULT 90 CHECK (audit_retention_days > 0), upload_retention_hours INTEGER NOT NULL DEFAULT 24 CHECK (upload_retention_hours > 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by_user_id UUID REFERENCES users(id) ON DELETE SET NULL); INSERT INTO system_settings (id) VALUES (1);
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_user_id UUID REFERENCES users(id) ON DELETE SET NULL, event_type TEXT NOT NULL, target_type TEXT, target_id UUID, ip INET, user_agent TEXT, device_id UUID REFERENCES devices(id) ON DELETE SET NULL, session_id UUID REFERENCES sessions(id) ON DELETE SET NULL, trace_id TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX audit_logs_created_idx ON audit_logs(created_at DESC); CREATE INDEX audit_logs_actor_created_idx ON audit_logs(actor_user_id, created_at DESC); CREATE INDEX audit_logs_event_created_idx ON audit_logs(event_type, created_at DESC);
